import{_ as t,o,c as r,ag as a}from"./chunks/framework.B9unkguw.js";const c=JSON.parse('{"title":"GeoView (Tech Preview)","description":"","frontmatter":{},"headers":[],"relativePath":"en/qgc-user-guide/fly_view/geoview.md","filePath":"en/qgc-user-guide/fly_view/geoview.md"}'),i={name:"en/qgc-user-guide/fly_view/geoview.md"};function n(s,e,l,d,h,g){return o(),r("div",null,e[0]||(e[0]=[a('<h1 id="geoview-tech-preview" tabindex="-1">GeoView (Tech Preview) <a class="header-anchor" href="#geoview-tech-preview" aria-label="Permalink to &quot;GeoView (Tech Preview)&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>GeoView is an experimental technology preview and is under active development. Expect missing features and rough edges. It is too early to report issues against this feature — there is still too much work left to do.</p></div><p>GeoView is a new map engine for QGroundControl that renders a single, seamless 2D/3D map: satellite/street imagery draped over real terrain elevation, with Google Earth-style camera controls. It displays your vehicles, the planned mission (with waypoint markers, connecting path, and drop lines showing each waypoint&#39;s height above the terrain), the flown flight path, the launch location, and the ground station position — all in true 3D.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>GeoView is currently a display-only view. You must still use the regular <a href="./fly_view.html">Fly View</a> to control the vehicle (arm, takeoff, guided actions, mission control, and so on).</p></div><p>The long-term goal is for the GeoView engine to eventually replace all map usage throughout QGroundControl, including the Fly and Plan views, providing one consistent 2D/3D map experience everywhere.</p><h2 id="enabling-geoview" tabindex="-1">Enabling GeoView <a class="header-anchor" href="#enabling-geoview" aria-label="Permalink to &quot;Enabling GeoView&quot;">​</a></h2><p>GeoView is disabled by default. To enable it, go to <strong>Application Settings &gt; GeoView</strong> and turn on <strong>Enable GeoView (preview)</strong>. It then appears in the view selector dropdown in the main toolbar.</p><h2 id="view-controls" tabindex="-1">View Controls <a class="header-anchor" href="#view-controls" aria-label="Permalink to &quot;View Controls&quot;">​</a></h2><p>Camera gestures follow Google Earth semantics: the ground point under the cursor when a gesture starts stays pinned under the cursor throughout the gesture.</p><ul><li><strong>Mouse:</strong><ul><li><strong>Pan</strong>: Left-drag. The terrain point you grabbed follows the cursor.</li><li><strong>Orbit (rotate)</strong>: Right-drag or middle-drag. The view rotates around the ground point you pressed on (marked by a pivot ring): left/right changes heading, up/down changes tilt between top-down and near-horizontal.</li><li><strong>Zoom</strong>: Scroll wheel or trackpad scroll. Zooms toward/away from the point under the cursor.</li></ul></li><li><strong>Touch:</strong><ul><li><strong>Pan</strong>: Single-finger drag.</li><li><strong>Zoom</strong>: Two-finger pinch, centered on the pinch point.</li><li><strong>Rotate</strong>: Two-finger twist.</li></ul></li></ul><h3 id="keyboard-support" tabindex="-1">Keyboard Support <a class="header-anchor" href="#keyboard-support" aria-label="Permalink to &quot;Keyboard Support&quot;">​</a></h3><p>Keyboard modifiers provide alternatives to the multi-button mouse gestures (useful with one-button mice and trackpads):</p><ul><li><strong>Shift + left-drag</strong>: Orbit, same as right/middle-drag.</li><li><strong>Ctrl + left-drag</strong>: First-person look. The camera stays in place and the view rotates, like turning your head — drag toward where you want to look. On macOS both <strong>Ctrl</strong> and <strong>Cmd</strong> work.</li></ul><h3 id="_2d-3d-modes" tabindex="-1">2D/3D Modes <a class="header-anchor" href="#_2d-3d-modes" aria-label="Permalink to &quot;2D/3D Modes&quot;">​</a></h3><ul><li>The <strong>3D/2D</strong> button in the top-right switches between modes. Switching animates the camera tilt and flattens/raises the terrain; 2D mode behaves like a traditional top-down map (tilt is locked).</li><li>The <strong>compass</strong> button rotates with the current heading; click it to animate the view back to north-up.</li></ul><h2 id="imagery-and-terrain" tabindex="-1">Imagery and Terrain <a class="header-anchor" href="#imagery-and-terrain" aria-label="Permalink to &quot;Imagery and Terrain&quot;">​</a></h2><p>GeoView drapes the same map imagery you have selected in <strong>Application Settings &gt; Maps</strong> over its terrain surface. Terrain elevation comes from the Mapzen/Tilezen terrain tiles dataset (SRTM, 3DEP, GMTED2010, ETOPO1); attribution is shown in the lower-left overlay.</p>',17)]))}const p=t(i,[["render",n]]);export{c as __pageData,p as default};
